function dashboard_nav(string $active): void {
    $u = user(); $links = ['Overview' => '/dashboard.php', 'My enquiries' => '/contact.php'];
    if (in_array($u['role'], ['staff','admin'], true)) $links += ['Packages' => '/staff/packages.php', 'Bookings' => '/staff/bookings.php', 'Enquiries' => '/staff/queries.php'];
    if ($u['role'] === 'admin') $links += ['Users' => '/admin/users.php', 'Reports' => '/admin/reports.php'];
    echo '<nav class="dashboard-nav" aria-label="Dashboard">'; foreach ($links as $name => $url) echo '<a class="' . ($name === $active ? 'selected' : '') . '" href="' . $url . '">' . e($name) . '</a>'; echo '</nav>';
}
